<div class="d-flex justify-content-between flex-wrap gap-3 mb-4"><div><h2 class="h4">Conferir linha <?= (int)$origin['linha'] ?></h2><p class="text-muted mb-0"><?= ge($origin['arquivo']) ?> · <?= ge($origin['aba']) ?></p></div><a class="btn btn-light align-self-start" href="/admin/gadsan/importacoes/<?= (int)$origin['importacao_id'] ?>">Voltar à importação</a></div>
